s = input().strip()
if not s:
    print(0)
else:
    runs = []
    current = s[0]
    count = 1
    for c in s[1:]:
        if c == current:
            count += 1
        else:
            runs.append(count)
            current = c
            count = 1
    runs.append(count)
    res = 0
    for r in runs:
        if r % 2 == 0:
            res += 1
    print(res)
